class Solution {
    public int equalDigitFrequency(String s) {
        final long M1 = 1_000_000_007L, M2 = 998_244_353L;
        int n = s.length();
        Set<Long> seen = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int[] cnt = new int[10];
            int distinct = 0, max = 0;
            long h1 = 0, h2 = 0;
            for (int j = i; j < n; j++) {
                int d = s.charAt(j) - '0';
                if (cnt[d]++ == 0) distinct++;
                max = Math.max(max, cnt[d]);
                h1 = (h1 * 11 + d + 1) % M1;
                h2 = (h2 * 13 + d + 1) % M2;
                if (max * distinct == j - i + 1) seen.add(h1 * 1_000_000_009L + h2);
            }
        }
        return seen.size();
    }
}
